    facts:[["Nickname","Brick Corps"],["Founded","1947–1948"],["Status","Civilian, uniformed, paid"],["Membership","Nominally voluntary"],["Peak strength","c. 250,000–300,000 direct workers"],["Peak year","1949"],["Principal work","Housing, utilities, transport, ports, and public buildings"],["Successor","Royal Civil Works Service"]]
