    facts:[["Royal assent","1949"],["Purpose","Preserve a defense-industrial floor"],["Naval focus","ASW, escorts, submarines, minesweepers, auxiliaries"],["Air focus","Interceptors, naval aircraft, radar, signals"],["Industrial means","Minimum orders, tooling, trials, and research"],["Excluded strategy","Symmetric prestige race"],["Political basis","Cross-party shifting majority"],["Long-term role","Foundation of the Siege Commonwealth arsenal"]]
